package com.phoenix.business.web;import com.phoenix.business.service.ReportService;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reports") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class ReportController {private final ReportService reports;@GetMapping(value="/members.xlsx",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> members()throws Exception{return file("members.xlsx",reports.members());}@GetMapping(value="/payments.xlsx",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> payments()throws Exception{return file("payments.xlsx",reports.payments());}private ResponseEntity<byte[]> file(String n,byte[] b){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+n+"\"").body(b);}}
